// ============ 导出数据到本地文件（云端不可用时的备用方案）============
function exportDataToLocalFile() {
  const data = {};
  data.shops = Cache.get('shops') || [];
  data.cb_product_costs = Cache.get('cb_product_costs') || [];
  data.cb_shipping_rates = Cache.get('cb_shipping_rates') || [];
  // 收集所有店铺的数据
  const shops = data.shops;
  data.cb_orders = [];
  data.cb_refunds = [];
  data.cb_reviews = [];
  data.cb_daily = [];
  data.cb_sku_reviews = [];
  data.shop_products = [];
  for (const shop of shops) {
    const sid = shop.id;
    (Cache.get('cb_orders_' + sid) || []).forEach(r => { r._shopId = sid; data.cb_orders.push(r); });
    (Cache.get('cb_refunds_' + sid) || []).forEach(r => { r._shopId = sid; data.cb_refunds.push(r); });
    (Cache.get('cb_reviews_' + sid) || []).forEach(r => { r._shopId = sid; data.cb_reviews.push(r); });
    (Cache.get('cb_daily_' + sid) || []).forEach(r => { r._shopId = sid; data.cb_daily.push(r); });
    (Cache.get('cb_sku_reviews_' + sid) || []).forEach(r => { r._shopId = sid; data.cb_sku_reviews.push(r); });
    (Cache.get('shop_products_' + sid) || []).forEach(r => { r._shopId = sid; data.shop_products.push(r); });
  }
  
  const json = JSON.stringify(data, null, 2);
  const blob = new Blob([json], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = '电商数据备份_' + new Date().toISOString().slice(0,10) + '.json';
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 1000);
  
  let totalRows = data.shops.length + data.cb_product_costs.length + data.cb_shipping_rates.length 
                  + data.cb_orders.length + data.cb_refunds.length + data.cb_reviews.length 
                  + data.cb_daily.length + data.cb_sku_reviews.length + data.shop_products.length;
  showToast('📥 数据已导出到本地文件（' + totalRows + ' 条记录）', 'success');
}

// ============ 从本地文件导入数据 ============
function importDataFromLocalFile(file, callback) {
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = JSON.parse(e.target.result);
      if (!data.shops || !Array.isArray(data.shops)) throw new Error('无效的备份文件');
      
      // 写入所有数据
      if (data.shops) Cache.set('shops', data.shops);
      if (data.cb_product_costs) Cache.set('cb_product_costs', data.cb_product_costs);
      if (data.cb_shipping_rates) Cache.set('cb_shipping_rates', data.cb_shipping_rates);
      
      // 按店铺写入
      for (const row of (data.cb_orders || [])) {
        const sid = row._shopId || row.shop_id;
        if (!sid) continue;
        const list = Cache.get('cb_orders_' + sid) || [];
        list.unshift(row);
        Cache.set('cb_orders_' + sid, list);
      }
      for (const row of (data.cb_refunds || [])) {
        const sid = row._shopId || row.shop_id;
        if (!sid) continue;
        const list = Cache.get('cb_refunds_' + sid) || [];
        list.unshift(row);
        Cache.set('cb_refunds_' + sid, list);
      }
      for (const row of (data.cb_reviews || [])) {
        const sid = row._shopId || row.shop_id;
        if (!sid) continue;
        const list = Cache.get('cb_reviews_' + sid) || [];
        list.unshift(row);
        Cache.set('cb_reviews_' + sid, list);
      }
      for (const row of (data.cb_daily || [])) {
        const sid = row._shopId || row.shop_id;
        if (!sid) continue;
        const list = Cache.get('cb_daily_' + sid) || [];
        list.unshift(row);
        Cache.set('cb_daily_' + sid, list);
      }
      for (const row of (data.cb_sku_reviews || [])) {
        const sid = row._shopId || row.shop_id;
        if (!sid) continue;
        const list = Cache.get('cb_sku_reviews_' + sid) || [];
        list.unshift(row);
        Cache.set('cb_sku_reviews_' + sid, list);
      }
      for (const row of (data.shop_products || [])) {
        const sid = row._shopId || row.shop_id;
        if (!sid) continue;
        const list = Cache.get('shop_products_' + sid) || [];
        list.unshift(row);
        Cache.set('shop_products_' + sid, list);
      }
      
      showToast('✅ 数据导入成功！共恢复 ' + (data.shops||[]).length + ' 家店铺', 'success');
      renderShopNav();
      navigate(currentPage, currentParam);
      if (callback) callback(true);
    } catch(err) {
      showToast('❌ 导入失败: ' + err.message, 'error');
      if (callback) callback(false);
    }
  };
  reader.readAsText(file);
}

// ============ 全局总览页面（展示有权限店铺每日数据） ============
function renderOverview() {
  const container = document.getElementById('page-overview');
  if (!container) return;
  
  const shops = getVisibleShops ? getVisibleShops() : (DB.getShops ? DB.getShops() : []);
  const today = new Date().toISOString().slice(0, 10);
  const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  
  let rows = [];
  shops.forEach(shop => {
    const isCross = CROSS_BORDER_PLATFORMS && CROSS_BORDER_PLATFORMS.has(shop.platform);
    const isDomestic = DOMESTIC_PLATFORMS && DOMESTIC_PLATFORMS.has(shop.platform);
    
    let todayData = null, yesterdayData = null;
    
    if (isCross && typeof CrossBorderDailyDB !== 'undefined') {
      const all = CrossBorderDailyDB.getAll(shop.id);
      todayData = all.find(r => r.date === today) || null;
      yesterdayData = all.find(r => r.date === yesterday) || null;
    } else if (isDomestic && typeof DB !== 'undefined' && DB.getSalesData) {
      // 国内店铺使用 sales 数据汇总（兼容）
      const sales = DB.getSalesData().filter(r => r.shop_id === shop.id || r.shopId === shop.id);
      todayData = {
        visitors: 0,
        paid_buyers: 0,
        paid_items: 0,
        paid_amount: sales.filter(r => r.date === today).reduce((s, r) => s + (r.revenue || 0), 0)
      };
    }
    
    // 订单数
    let ordersToday = 0, ordersYesterday = 0;
    if (typeof CBOrderDB !== 'undefined') {
      const cbOrders = CBOrderDB.getAll(shop.id).filter(o => (o.sale_amount || 0) > 0 && o.date === today);
      ordersToday = cbOrders.length;
    }
    
    rows.push({
      shop: shop,
      today: todayData,
      yesterday: yesterdayData,
      ordersToday: ordersToday
    });
  });
  
  // 计算环比变化
  function changeRate(today, yesterday) {
    if (!today || !yesterday || yesterday === 0) return '';
    const diff = today - yesterday;
    const pct = (diff / yesterday * 100).toFixed(1);
    return `<span style="color:${diff >= 0 ? '#10b981' : '#f87171'};font-size:11px">${diff >= 0 ? '↑' : '↓'} ${Math.abs(pct)}%</span>`;
  }
  
  function fmtNum(n) {
    if (n === null || n === undefined || isNaN(n)) return '-';
    return Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
  }
  
  function fmtCurrency(n, currency) {
    if (n === null || n === undefined || isNaN(n)) return '-';
    const symbol = currency === 'CNY' ? '¥' : '$';
    return symbol + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  
  container.innerHTML = `
    <div class="page-header" style="margin-bottom:20px">
      <h2 style="margin:0;font-size:18px;font-weight:600">总览</h2>
      <p style="margin:6px 0 0;color:#64748b;font-size:13px">观察每个店铺每日变化 · 数据日期：${today}</p>
    </div>
    <div class="card">
      <div style="overflow-x:auto">
        <table style="width:100%;border-collapse:collapse;font-size:13px">
          <thead>
            <tr style="border-bottom:1px solid #e2e8f0;background:#f8fafc">
              <th style="padding:12px 16px;text-align:left;font-weight:600">店铺</th>
              <th style="padding:12px 16px;text-align:center;font-weight:600">平台</th>
              <th style="padding:12px 16px;text-align:right;font-weight:600">访客</th>
              <th style="padding:12px 16px;text-align:right;font-weight:600">支付人数</th>
              <th style="padding:12px 16px;text-align:right;font-weight:600">支付件数</th>
              <th style="padding:12px 16px;text-align:right;font-weight:600">支付金额</th>
              <th style="padding:12px 16px;text-align:right;font-weight:600">订单数</th>
              <th style="padding:12px 16px;text-align:center;font-weight:600">操作</th>
            </tr>
          </thead>
          <tbody>
            ${rows.length === 0 ? `<tr><td colspan="8" style="padding:40px;text-align:center;color:#64748b">暂无可见店铺</td></tr>` : rows.map(r => {
              const shop = r.shop;
              const today = r.today || {};
              const yesterday = r.yesterday || {};
              const currency = (typeof getPlatformCurrency === 'function') ? getPlatformCurrency(shop) : ((CROSS_BORDER_PLATFORMS && CROSS_BORDER_PLATFORMS.has(shop.platform)) ? 'USD' : 'CNY');
              return `
                <tr style="border-bottom:1px solid #f1f5f9">
                  <td style="padding:12px 16px">
                    <div style="display:flex;align-items:center;gap:8px">
                      <span class="color-dot" style="background:${shop.color || '#6366f1'};width:8px;height:8px;border-radius:50%;display:inline-block"></span>
                      <span>${shop.name}</span>
                    </div>
                  </td>
                  <td style="padding:12px 16px;text-align:center;color:#64748b">${shop.platform}</td>
                  <td style="padding:12px 16px;text-align:right">
                    ${fmtNum(today.visitors)}
                    ${changeRate(Number(today.visitors), Number(yesterday.visitors))}
                  </td>
                  <td style="padding:12px 16px;text-align:right">
                    ${fmtNum(today.paid_buyers)}
                    ${changeRate(Number(today.paid_buyers), Number(yesterday.paid_buyers))}
                  </td>
                  <td style="padding:12px 16px;text-align:right">
                    ${fmtNum(today.paid_items)}
                    ${changeRate(Number(today.paid_items), Number(yesterday.paid_items))}
                  </td>
                  <td style="padding:12px 16px;text-align:right;font-weight:600">
                    ${fmtCurrency(today.paid_amount, currency)}
                    ${changeRate(Number(today.paid_amount), Number(yesterday.paid_amount))}
                  </td>
                  <td style="padding:12px 16px;text-align:right">${r.ordersToday || '-'}</td>
                  <td style="padding:12px 16px;text-align:center">
                    <button class="btn-secondary btn-sm" onclick="navigate('shop-detail','${shop.id}')">详情</button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

window.renderOverview = renderOverview;

// ===== V6 兜底：把全局函数可靠暴露到 window（兼容内联事件处理器） =====
(function() {
  const names = [
    'navigate','renderDashboard','renderStyles','renderRevenue','renderProfit',
    'renderAlert','renderImport','renderAcademy','addShop','openModal','closeModal',
    'showToast','updateExchangeRateDisplay','fetchExchangeRate','fmtMoneyByCurrency',
    'toCNY','getShopCurrency','normalizeDate','openAddModal','exportDataToLocalFile',
    'importData','saveShop','editShop','deleteShop','renderOverview','renderShopDetail',
    // === V116 修复：补齐所有 onclick 引用的全局函数 ===
    'openAddShop','openEditShopModal','saveEditShop',
    'adminDeleteUser','batchDeleteReviews','cancelBackup','confirmGrant',
    'doLogin','doLogout','doRegister','doSubmitResetRequest',
    'exportCBReviews','manualSync','openCreateRoleModal','openEditCBReviewModal',
    'openGrantModal','pushAllDataToCloud','refreshCurrentPage','removeCBReview',
    'revokeAccess','saveAllPermissions','selectRoleColor','showForgotForm',
    'showMobileMenu','submitArticle','submitCreateRole','toggleBigScreen',
    'togglePermCheckbox','togglePwd','toggleShopNav'
  ];
  names.forEach(function(n) {
    try {
      if (typeof window[n] !== 'function' && typeof eval(n) === 'function') {
        window[n] = eval(n);
      }
    } catch(e) {}
  });

  // === V116 修复：再延迟 200ms 重试一次（处理 defer 加载顺序：auth-v6-safe.js 之后才执行） ===
  setTimeout(function() {
    names.forEach(function(n) {
      try {
        if (typeof window[n] !== 'function' && typeof eval(n) === 'function') {
          window[n] = eval(n);
          console.log('[V6] 延迟挂载 window.' + n);
        }
      } catch(e) {}
    });
  }, 200);
  // 保险：再延迟 1000ms 兜底（处理动态加载场景）
  setTimeout(function() {
    names.forEach(function(n) {
      try {
        if (typeof window[n] !== 'function' && typeof eval(n) === 'function') {
          window[n] = eval(n);
        }
      } catch(e) {}
    });
  }, 1000);

  // 对可能被内联调用但 v4 中没有的函数，提供 no-op 兜底
  const noops = {
    'unloadRender': function(){},
    'dbSyncFailure': function(){},
    'checkEditPermission': function(){ return true; },
    'checkPagePermission': function(){ return true; },
    'handleKeypress': function(e){ if(e && e.key === 'Enter' && typeof window.doLogin === 'function') window.doLogin(); },
    'doLoginShowError': function(msg){
      var el = document.getElementById('login-error');
      if(el){ el.textContent = msg; el.style.display = 'block'; }
    },
    'doRegisterShowError': function(msg){
      var el = document.getElementById('register-error');
      if(el){ el.textContent = msg; el.style.display = 'block'; }
    },
    'showError': function(form, msg){
      var el = document.getElementById((form||'login') + '-error');
      if(el){ el.textContent = msg; el.style.display = 'block'; }
    },
    'showSuccess': function(form, msg){ console.log('['+form+']', msg); }
  };
  Object.keys(noops).forEach(function(k){
    try { if(typeof window[k] !== 'function') window[k] = noops[k]; } catch(e){}
  });

  // 暴露 DB 对象（如果存在全局变量）
  const dbNames = ['CBOrderDB','CBShippingRateDB','CrossBorderDailyDB','CBRefundDB','CBReviewDB','CBSkuReviewDB','CBProductCostDB','LocalUsers','ACADEMY','KnowledgeDB'];
  dbNames.forEach(function(n){
    try { if(typeof window[n] === 'undefined' && typeof eval(n) !== 'undefined') window[n] = eval(n); } catch(e){}
  });

  console.log('[App] V6 兜底已加载');
})();

/* ============ V161: 跨境重数据库内存缓存层 ============
 * 根因：CBOrderDB.getAll 等每次都 JSON.parse(localStorage 中 64K 订单 ≈ 30MB)，
 *       切 Tab 重复解析 → 卡顿数秒；renderOptimizeTab 旧逻辑还同步写 30MB → 白屏。
 * 修复：getAll 解析后缓存到内存；save/add/upsert/clear 等写操作后按 shopId 失效；
 *       云端同步是直写 localStorage（绕过 DB 对象），故 syncFromSupabase 完成后
 *       调用 window.__invalidateAllDBCache() 统一失效，下次读取即拉到最新数据。
 */
(function(){
  var _names=['CBOrderDB','CBRefundDB','CBReviewDB','CBSkuReviewDB','CrossBorderDailyDB'];
  function _getDB(name){
    try {
      if(name==='CBOrderDB') return CBOrderDB;
      if(name==='CBRefundDB') return CBRefundDB;
      if(name==='CBReviewDB') return CBReviewDB;
      if(name==='CBSkuReviewDB') return CBSkuReviewDB;
      if(name==='CrossBorderDailyDB') return CrossBorderDailyDB;
    } catch(e){}
    return null;
  }
  _names.forEach(function(name){
    var db=_getDB(name);
    if(!db||db.__cached) return;
    db.__cache={};
    var origGetAll=db.getAll.bind(db);
    db.getAll=function(shopId){
      if(shopId!=null&&this.__cache[shopId]) return this.__cache[shopId];
      var v=origGetAll(shopId);
      if(shopId!=null) this.__cache[shopId]=v;
      return v;
    };
    var _inv=function(shopId){ if(shopId!=null) delete db.__cache[shopId]; else db.__cache={}; };
    ['save','add','upsert','update','remove','delete','clear','del','set'].forEach(function(m){
      if(typeof db[m]==='function'){
        var orig=db[m].bind(db);
        db[m]=function(){ var r=orig.apply(db,arguments); _inv(arguments[0]); return r; };
      }
    });
    db.__invalidate=_inv;
    db.__cached=true;
  });
  window.__invalidateAllDBCache=function(){
    _names.forEach(function(n){ var d=_getDB(n); if(d&&d.__invalidate) d.__invalidate(); });
  };
  console.log('[Cache] 跨境重数据库内存缓存层已启用 ✓');
})();
